Future<void> _openEditorGuarded(BuildContext context, Order order) async {
  final saved = await Navigator.push<bool>(
    context,
    MaterialPageRoute(builder: (_) => EditorPage(order: order)),
  );
  if (!context.mounted || saved != true) return;
  await api.refresh(order.id);
  if (!context.mounted) return;
  ScaffoldMessenger.of(context).showSnackBar(
    const SnackBar(content: Text('Saved')),
  );
}

// RIGHT — capture before the gap when the message must appear anyway
Future<void> _submit(BuildContext context) async {
  final messenger = ScaffoldMessenger.of(context);
  final navigator = Navigator.of(context);
  final ok = await api.submit();
  if (ok) navigator.pop(true);
  messenger.showSnackBar(SnackBar(content: Text(ok ? 'Sent' : 'Failed')));
}

