class AppRouterDelegate extends RouterDelegate<Object>
    with ChangeNotifier, PopNavigatorRouterDelegateMixin<Object> {
  @override
  final navigatorKey = GlobalKey<NavigatorState>();

  final List<Order> _openOrders = [];

  void open(Order o) {
    _openOrders.add(o);
    notifyListeners();
  }

  @override
  Widget build(BuildContext context) {
    return Navigator(
      key: navigatorKey,
      pages: [
        const MaterialPage(key: ValueKey('home'), child: HomePage()),
        for (final o in _openOrders)
          MaterialPage(
            // Stable identity — without it, inserting at the front
            // hands OrderPage(7)'s State to OrderPage(9)
            key: ValueKey('order-${o.id}'),
            child: OrderPage(order: o),
          ),
      ],
      // Flutter 3.24+: replaces the deprecated onPopPage
      onDidRemovePage: (page) {
        final key = page.key;
        if (key is ValueKey<String> &&
            key.value.startsWith('order-')) {
          _openOrders.removeWhere((o) => 'order-${o.id}' == key.value);
          notifyListeners();
        }
      },
    );
  }

  @override
  Future<void> setNewRoutePath(Object configuration) async {}
}

